insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_116_v1'
from (values
('127.819.d.1.A',3,'During a shift handoff at a job shop, a lead machinist explains in two clear sentences which fixture is loaded, which program is running and what to watch for. She is expressing ideas to others in a:','["clear, concise and effective manner through speaking", "silent manner", "unclear manner", "long, rambling manner"]'::jsonb,0,'Clear speech prevents mistakes.','original'),
('127.819.d.1.A',4,'When briefing a crew at the start of a run, the best approach is to:','["mumble the details", "state the key points briefly and check for questions", "skip the details", "talk about unrelated topics"]'::jsonb,1,'Concise briefings keep teams aligned.','original'),
('127.819.d.1.B',3,'An apprentice writes an e-mail that lists the part number, the issue and the action needed so the engineer can reply without a call. She is conveying:','["unfinished sentences", "confusing notes", "written information that is easily understandable to others", "vague hints"]'::jsonb,2,'Clear writing saves time.','original'),
('127.819.d.1.B',4,'A good written shift report for a CNC cell includes:','["only a signature", "only the weather", "only a joke", "what was run, any problems and what the next shift must do"]'::jsonb,3,'Useful handoff notes.','original'),
('127.819.d.1.C',3,'A new hire at a Texas fab shop arrives before the start of the shift, clocks in on time and keeps her work area ready. She is demonstrating:','["acceptable work ethics in reporting for duty and performing assigned tasks", "casual lateness", "poor planning", "avoiding duties"]'::jsonb,0,'Reliability is a core work ethic.','original'),
('127.819.d.1.C',4,'A worker who cannot make it to a scheduled shift should:','["come in late without telling anyone", "notify the supervisor as early as possible", "blame a coworker", "say nothing"]'::jsonb,1,'Early notice allows coverage.','original'),
('127.819.d.1.D',3,'A machinist keeps cell phone use for breaks, wears the required safety gear and speaks respectfully to visitors on the floor. She is conducting herself:','["rudely", "carelessly", "in a manner acceptable for the profession and work situation", "impulsively"]'::jsonb,2,'Professional conduct fits the job.','original'),
('127.819.d.1.D',4,'Which action best shows professional conduct around customers touring a shop?','["playing music loudly", "leaving tools in the aisle", "shouting across the floor", "using polite language and staying within safe walkways"]'::jsonb,3,'Respect and safety.','original'),
('127.819.d.1.E',3,'A technician discovers that the inspection form was filled in before the parts were measured and decides to report it and follow the quality procedure instead of going along. She is choosing:','["the ethical course of action and complying with rules and regulations", "the fastest course", "the easy course", "the silent course"]'::jsonb,0,'Ethics means honesty and compliance.','original'),
('127.819.d.1.E',4,'If an inspection result is out of tolerance, the ethical response is to:','["change the number", "record the actual measurement and report it", "hide the part", "ship it anyway"]'::jsonb,1,'Honest data protects customers.','original'),
('127.819.d.1.F',3,'A quality technician rechecks a gauge reading, compares the thread callout to the print and reads the notes for finish requirements before approving a lot. She is reviewing:','["only the cover page", "only the headline", "with a critical eye the fine, detailed aspects of both quantitative and qualitative information", "only the color"]'::jsonb,2,'Details matter in quality.','original'),
('127.819.d.1.F',4,'A measurement that gives a number, such as a diameter of 0.750 inch, is an example of:','["a guess", "opinion only", "qualitative information", "quantitative information"]'::jsonb,3,'Numbers are quantitative.','original'),
('127.819.d.1.G',3,'A team reviews three weeks of scrap reports and notices most rejects come from the same lathe on second shift, then traces it to a worn collet. They are evaluating systems and identifying:','["causes, problems and patterns to recommend improvements", "only colors", "only blame", "only prices"]'::jsonb,0,'Data reveals patterns.','original'),
('127.819.d.1.G',4,'After finding that a machine produces undersized parts every Monday, the best next step is to:','["stop recording data", "look for what changes on Monday and test that cause", "ignore the pattern", "replace every machine"]'::jsonb,1,'Investigate root causes.','original'),
('127.819.d.1.H',3,'A machinist reads the work instruction twice, asks the lead to explain one step aloud and follows the company safety policy to the letter. She is following:','["only her own ideas", "only shortcuts", "written and oral instructions and adhering to established business policies", "only rumors"]'::jsonb,2,'Follow instructions and policy.','original'),
('127.819.d.1.H',4,'If a written work instruction and a verbal request seem to conflict, the machinist should:','["pick the one she likes", "do both at once", "ignore both", "clarify with the supervisor before proceeding"]'::jsonb,3,'Clarify conflicts.','original'),
('127.819.d.1.I',3,'A worker lists the day''s jobs by due date, blocks time for setup and inspection and checks off each one so the hot job ships first. He is prioritizing tasks and:','["following schedules and working on goal-relevant activities", "doing unrelated tasks", "avoiding schedules", "working randomly"]'::jsonb,0,'Prioritization meets deadlines.','original'),
('127.819.d.1.I',4,'A job due tomorrow and a job due next week are both waiting. The better priority is to:','["start the job due next week", "start the job due tomorrow first", "start neither", "start the easiest"]'::jsonb,1,'Earlier deadlines come first.','original'),
('127.819.d.2.A',3,'A student programs and turns a stepped shaft with a groove and a thread to a NIMS Level 1 print and inspects every feature. She is producing:','["a poster", "a paper model", "a detailed turning part such as the NIMS Level 1 turning project", "a sculpture"]'::jsonb,2,'NIMS-style turning project.','original'),
('127.819.d.2.A',4,'For a NIMS Level 1 turned part, the final step before submitting it is to:','["guess at sizes", "paint it", "skip inspection", "inspect each feature against the print"]'::jsonb,3,'Final inspection.','original'),
('127.819.d.2.B',3,'A student mills a plate with a pocket, a 4-hole pattern and a contoured edge for a NIMS Level 1 submission. She is producing:','["a detailed milling part such as the NIMS Level 1 milling part", "a photo album", "a sketchbook", "a paper craft"]'::jsonb,0,'NIMS-style milling project.','original'),
('127.819.d.2.B',4,'A pocket on a milled part is:','["a flat sheet", "a recessed feature cut into the surface", "a raised pin", "a through-hole thread"]'::jsonb,1,'Pockets are recesses.','original'),
('127.819.d.3.A',3,'An operator changes from a 3/8-inch drill to a 1/2-inch end mill by hand for one job and uses the automatic changer for the next. She is performing:','["music changes", "scene changes", "various types of tool changes", "lighting changes"]'::jsonb,2,'Tool changes can be manual or automatic.','original'),
('127.819.d.3.A',4,'The safest time to change a tool manually on a CNC machine is when:','["the door is open and running", "the part is cutting", "the spindle is turning", "the spindle is stopped and the machine is in a safe condition"]'::jsonb,3,'Safe state first.','original'),
('127.819.d.3.B',3,'A shop uses tool holders that clamp into the spindle in seconds and already carry a preset tool length. They are demonstrating:','["quick change tooling used on CNC milling machines", "slow tooling", "handmade tooling", "glued tooling"]'::jsonb,0,'Quick-change reduces setup time.','original'),
('127.819.d.3.B',4,'A main benefit of presetting tools in quick-change holders is that it:','["adds more manual work", "shortens the time the machine sits idle during setup", "increases the noise", "increases spindle load"]'::jsonb,1,'Less downtime.','original'),
('127.819.d.3.C',3,'At the end of a job, a student wipes each holder and returns every tool to its labeled spot in a cabinet so edges are not nicked. She is demonstrating:','["tossing tools aside", "haphazard storage", "appropriate tool storage", "leaving tools out"]'::jsonb,2,'Good storage protects edges.','original'),
('127.819.d.3.C',4,'Storing end mills loose in a drawer so they hit each other can cause:','["better finishes", "sharper edges", "longer tool life", "chipped cutting edges"]'::jsonb,3,'Contact damages edges.','original'),
('127.819.d.3.D',3,'A student opens the offset page on the control and types a length value for tool 3 so the machine knows where the tip sits relative to the part. She is demonstrating the proper use of:','["tool offset registers", "clock settings", "menu lists", "wall paint"]'::jsonb,0,'Offset registers hold tool data.','original'),
('127.819.d.3.D',4,'The tool offset registers on a CNC control store information about each tool, such as its:','["brand history", "length and diameter", "color", "price"]'::jsonb,1,'Registers hold geometry.','original'),
('127.819.d.3.E',3,'A technician lowers a tool until it just touches a gauge block and reads the Z position to find the tool''s length compared with a reference. She is determining:','["a lunch break", "a delivery time", "tool offset length", "a work schedule"]'::jsonb,2,'Touch-off gives length offsets.','original'),
('127.819.d.3.E',4,'Compared with touching off every tool on the machine, using a presetter off the machine:','["adds machine time", "adds noise", "reduces accuracy always", "saves machine time"]'::jsonb,3,'Presetters work offline.','original'),
('127.819.d.3.F',3,'After measuring three tools, the student types each length and diameter into the correct register and double-checks the entries before running the first part. She is:','["entering tool offsets for a setup", "entering a contest", "entering a race", "entering a building"]'::jsonb,0,'Correct entries prevent crashes.','original'),
('127.819.d.3.F',4,'A wrong digit in a tool length offset can cause:','["a cleaner floor", "the tool to cut too deep or stop short of the part", "a quieter machine", "a faster part"]'::jsonb,1,'Offset errors cause crashes.','original'),
('127.819.d.4.A',3,'A job-shop apprentice confirms the safety door interlock works, keeps loose sleeves away from the spindle and checks that the bar feeder is secured before running the turning center. She is working:','["with the interlock bypassed", "without any guards", "with equipment found on and around a CNC lathe in a safe manner", "carelessly"]'::jsonb,2,'Lathe safety checks come before cycle start.','original'),
('127.819.d.4.A',4,'The safety door interlock on a CNC lathe is designed to:','["lock the part in place", "hold the coolant", "increase the cutting speed", "stop the spindle or prevent starting when the door is open"]'::jsonb,3,'Interlocks protect operators.','original'),
('127.819.d.4.B',3,'On a photo of a turning center, a student correctly labels the headstock, chuck, turret, tailstock and control panel and states what each does. She is naming and describing:','["the primary components of a CNC lathe", "parts of a kitchen", "parts of a bicycle", "parts of a skateboard"]'::jsonb,0,'Know the machine''s components.','original'),
('127.819.d.4.B',4,'The chuck on a CNC lathe is used to:','["store the tools", "grip and rotate the workpiece", "display the program", "hold the coolant"]'::jsonb,1,'The chuck holds the part.','original'),
('127.819.d.4.C',3,'Every Monday morning an operator checks the spindle lube, the hydraulic oil level and the chip conveyor on the turning center and logs the results. She is doing:','["decorating", "scheduling lunch", "preventative maintenance checks on a CNC lathe", "sweeping the parking lot"]'::jsonb,2,'PM checks prevent breakdowns.','original'),
('127.819.d.4.C',4,'Logging preventative maintenance checks is useful because it:','["replaces inspections", "hides problems", "adds paperwork only", "shows when service is due and tracks problems over time"]'::jsonb,3,'Records support maintenance.','original'),
('127.819.d.4.D',3,'With a handheld meter, a technician measures the percentage of concentrate in the coolant sump on the lathe and mixes in more concentrate when it reads low. She is testing the coolant for:','["proper density and adjusting it to protect parts and tools", "flavor", "color only", "price"]'::jsonb,0,'Right concentration protects parts.','original'),
('127.819.d.4.D',4,'Coolant mixed too lean on a CNC lathe is likely to:','["improve the finish", "allow rust and shorten tool life", "extend tool life", "stop all heat"]'::jsonb,1,'Weak coolant under-protects.','original'),
('127.819.d.4.E',3,'A student flips the main disconnect, waits for the control screen, clears any start-up alarms and sends the axes home before a first cut. She is performing:','["a power down", "a tool change", "a power up on a standard CNC lathe", "a data backup"]'::jsonb,2,'Follow the start-up sequence.','original'),
('127.819.d.4.E',4,'Power-up and homing on a CNC lathe is important because it:','["cools the spindle", "loads the program", "cleans the chips", "sets a known reference position for the axes"]'::jsonb,3,'Homing defines machine zero.','original'),
('127.819.d.4.F',3,'Using the pendant, a student moves the X and Z axes in small steps with the handwheel until the tool tip is a few thousandths from the bar face. She is demonstrating:','["the use of the jog controls on the operator panel", "skipping the setup", "running the program", "cutting at full speed"]'::jsonb,0,'Jogging positions axes manually.','original'),
('127.819.d.4.F',4,'The best jog setting when the tool is near the workpiece is:','["maximum rapid", "the smallest increment or slowest speed", "random", "no limit"]'::jsonb,1,'Small steps prevent crashes.','original'),
('127.819.d.4.G',3,'A student seats an insert in a tool holder, torques the screw and measures the overhang with a gauge before loading it into the lathe. She is demonstrating the ability to:','["skip measuring", "guess at tooling", "locate, assemble and measure tooling according to a setup sheet", "ignore the setup sheet"]'::jsonb,2,'Tooling follows the setup sheet.','original'),
('127.819.d.4.G',4,'A setup sheet for a CNC lathe typically lists:','["the lunch menu", "the weather", "the workers'' names", "each tool, its position and its offset information"]'::jsonb,3,'Setup sheets organize tooling.','original'),
('127.819.d.4.H',3,'Following the setup sheet, a student places tool 1 in turret position 1, tool 2 in position 2 and tool 3 in position 3 and tightens each holder. She is:','["installing tools and tool holders in the automatic tool changer locations", "removing the turret", "skipping the sheet", "painting the holders"]'::jsonb,0,'Tool positions must match the program.','original'),
('127.819.d.4.H',4,'If tool numbers in the turret do not match the program, the likely outcome is:','["a cleaner part", "the wrong tool will run, which can ruin the part or crash", "a quieter machine", "faster cycle time"]'::jsonb,1,'Mismatch is dangerous.','original'),
('127.819.d.4.I',3,'With a bar in the chuck, the student faces the end lightly, retracts, reads the Z coordinate and tells the control that this is part zero. She is:','["cleaning the chuck", "clearing the screen", "locating and setting the workpiece to zero on a CNC lathe", "resetting the clock"]'::jsonb,2,'Z zero is set at the part face.','original'),
('127.819.d.4.I',4,'Setting a part zero lets the program:','["use less power", "run faster", "ignore the part", "reference the part rather than the machine''s home"]'::jsonb,3,'Zero links the program to the part.','original'),
('127.819.d.4.J',3,'After touching off the stock, the student types the Z value into the G54 register so the program starts from the part face. She is setting:','["any required work offsets for the part to be machined after a basic setup", "a new password", "a new tool", "the time zone"]'::jsonb,0,'Work offsets reference part zero.','original'),
('127.819.d.4.J',4,'Which code commonly calls up the first stored work offset on a CNC control?','["S1200", "G54", "M30", "T0101"]'::jsonb,1,'G54 is the first work offset.','original'),
('127.819.d.4.K',3,'For each tool in the turret, the student enters X and Z geometry values and a nose radius so the control can place the cutting edge correctly. She is setting:','["a ringtone", "a clock", "the proper geometry/tool offsets for each tool in a standard tool turret", "a theme"]'::jsonb,2,'Geometry offsets locate each tool.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_116_v1'
from (values
('127.819.d.4.K',4,'If the X geometry offset for a turning tool is wrong by 0.010 inch, the finished diameter will be:','["perfect", "unchanged", "twice as accurate", "off by about the same amount"]'::jsonb,3,'Offsets move the cutting position.','original'),
('127.819.d.4.L',3,'After the first piece passes inspection, the operator runs the next ten parts in automatic mode while watching the load meter and chip flow. She is:','["operating a CNC lathe in automatic mode", "cleaning the machine", "editing a program", "calibrating the meter"]'::jsonb,0,'Automatic mode runs the cycle.','original'),
('127.819.d.4.L',4,'While a lathe runs in automatic mode, the operator should be ready to:','["leave the area", "press feed hold or emergency stop if something looks wrong", "open the door", "ignore alarms"]'::jsonb,1,'Stay alert and ready.','original'),
('127.819.d.4.M',3,'At the end of the day, the operator moves the turret to its safe position, cleans out the chips, switches off the control and then the main power. She is illustrating:','["a program edit", "a tool change", "the proper power down process on a CNC lathe", "a start-up"]'::jsonb,2,'Shut down in order.','original'),
('127.819.d.4.M',4,'Chips should be cleared from a CNC lathe at the end of the shift to:','["add noise", "hide wear", "slow the next shift", "prevent damage and keep the machine accurate and safe"]'::jsonb,3,'Clean machines run better.','original'),
('127.819.d.5.A',3,'Before running a vertical machining center, a student checks that the vise jaws are snug, the guard door shuts and nothing is left on the table. She is working:','["with equipment found on and around a CNC mill in a safe manner", "without checking", "with the guard removed", "with the door open"]'::jsonb,0,'CNC mill safety checks.','original'),
('127.819.d.5.A',4,'Which of the following should be removed from a mill''s table before running?','["the vise", "tools, wrenches and loose items", "the workpiece", "the clamps in use"]'::jsonb,1,'Loose items can become projectiles.','original'),
('127.819.d.5.B',3,'A student labels the spindle, column, saddle, table and control on a photo of a vertical machining center and states what each does. She is naming and describing:','["parts of a skateboard", "parts of a piano", "the primary components of a CNC mill", "parts of a refrigerator"]'::jsonb,2,'Know the machine''s components.','original'),
('127.819.d.5.B',4,'On a vertical mill, the table moves the workpiece in:','["no directions", "spindle speed only", "tool changes only", "X and Y directions"]'::jsonb,3,'The table moves in X and Y.','original'),
('127.819.d.5.C',3,'On Fridays an operator checks the way-lube reservoir, cleans the spindle taper and inspects the air filter on the machining center. She is performing:','["preventative maintenance checks on a CNC mill", "a program edit", "a tool storage check", "a safety quiz"]'::jsonb,0,'Regular PM maintains accuracy.','original'),
('127.819.d.5.C',4,'Debris on a spindle taper can cause:','["longer tool life", "poor tool seating and runout", "less wear", "better accuracy"]'::jsonb,1,'Clean tapers seat tools.','original'),
('127.819.d.5.D',3,'A technician pulls a sample from the mill''s coolant tank, reads the concentration on a refractometer and tops up with the right mix. She is testing the coolant for:','["a smell", "a color match", "proper density and adjusting it", "a taste"]'::jsonb,2,'Check concentration regularly.','original'),
('127.819.d.5.D',4,'Too-rich coolant mixed on a mill can leave:','["no residue", "a better finish always", "less foam always", "a sticky residue and cause skin irritation"]'::jsonb,3,'Over-concentration has downsides.','original'),
('127.819.d.5.E',3,'An operator turns the main disconnect on, waits for the control to boot, clears the alarms and presses the reference return button for every axis. She is performing:','["a power up on a standard CNC mill", "a tool setup", "a shutdown", "a program edit"]'::jsonb,0,'Start-up sequence.','original'),
('127.819.d.5.E',4,'On start-up, a CNC mill needs to be homed so that:','["the coolant turns on", "the control knows where each axis is", "the tools are cleaned", "the spindle speeds up"]'::jsonb,1,'Homing establishes a reference.','original'),
('127.819.d.5.F',3,'With the pendant, a student spins the handwheel one click at a time to bring the cutter edge down toward the part surface. She is demonstrating:','["editing code", "changing a tool", "the use of the jog controls on the operator panel of a CNC mill", "running a program"]'::jsonb,2,'Jogging moves axes by hand.','original'),
('127.819.d.5.F',4,'When jogging a mill''s Z axis close to the part, the safest approach is to:','["use rapid mode", "look away", "jog quickly", "use a small handwheel increment while watching the tool"]'::jsonb,3,'Go slowly near the work.','original'),
('127.819.d.5.G',3,'A student tightens an end mill in a collet, sets the stickout to match the setup sheet and measures the assembled tool before loading it. She is demonstrating the ability to:','["locate, assemble and measure tooling using a setup sheet", "skip measuring", "guess the length", "ignore the sheet"]'::jsonb,0,'Follow the setup sheet.','original'),
('127.819.d.5.G',4,'A longer stickout on an end mill generally:','["improves finish", "reduces rigidity and can cause chatter", "increases rigidity", "reduces vibration"]'::jsonb,1,'Overhang reduces stiffness.','original'),
('127.819.d.5.H',3,'The student loads the face mill into pocket 1 of the tool carousel, the drill into pocket 2 and the end mill into pocket 3 as shown on the setup sheet. She is:','["painting the holders", "guessing at pockets", "installing tools and tool holders in the automatic tool changer locations", "removing the carousel"]'::jsonb,2,'Pocket positions match the program.','original'),
('127.819.d.5.H',4,'A tool called as T2 in a mill program must be located in:','["the coolant tank", "pocket 5", "the vise", "tool pocket 2 of the changer"]'::jsonb,3,'T numbers match pockets.','original'),
('127.819.d.5.I',3,'A student brings an edge finder against the left and front sides of the stock and records those machine positions as the part''s X and Y zero. She is:','["locating and setting the workpiece to zero on a CNC mill", "resetting a password", "resetting a tool", "resetting a timer"]'::jsonb,0,'Edge finding sets zero.','original'),
('127.819.d.5.I',4,'The Z zero on a mill part is often set at:','["the tool changer", "the top surface of the stock", "the machine ceiling", "the bottom of the vise"]'::jsonb,1,'Top of stock is common.','original'),
('127.819.d.5.J',3,'After finding the stock edges and top, the student types the X, Y and Z positions into the G55 register for the second fixture. She is setting:','["a new date", "a new password", "any required work offsets for the part to be machined after a basic setup", "a screen saver"]'::jsonb,2,'Work offsets locate each fixture.','original'),
('127.819.d.5.J',4,'Using several work offsets such as G54 and G55 allows a mill to:','["skip the setup", "run without tools", "ignore the print", "machine more than one part or fixture in a single program"]'::jsonb,3,'Multiple offsets support multiple fixtures.','original'),
('127.819.d.5.K',3,'The student enters each cutter''s length and diameter in the tool table so the control can place the tip correctly and apply compensation. She is setting:','["the proper geometry/tool offsets for each tool in a standard tool changer", "a ringtone", "a clock", "a theme"]'::jsonb,0,'Geometry offsets are per tool.','original'),
('127.819.d.5.K',4,'If a cutter''s diameter offset is entered too small, a profile cut will leave:','["a bigger hole", "extra material on the part", "a perfect size", "too little material"]'::jsonb,1,'Under-compensation leaves stock.','original'),
('127.819.d.5.L',3,'After the first part passes inspection, the operator closes the door and lets the mill machine the batch hands-free while she monitors the screen. She is:','["editing code", "cleaning the vise", "operating a CNC mill in automatic mode", "resetting offsets"]'::jsonb,2,'Automatic mode runs production.','original'),
('127.819.d.5.L',4,'When a CNC mill makes an unusual noise during an automatic cycle, the operator should:','["open the door during the cut", "increase the speed", "ignore it", "press feed hold or emergency stop and investigate"]'::jsonb,3,'Stop and investigate abnormal sounds.','original'),
('127.819.d.5.M',3,'At day''s end, the operator moves the table to a safe position, cleans out the chips and powers off the control before turning off the main disconnect. She is illustrating:','["the proper power down process on a CNC mill", "a program edit", "a power up", "a tool change"]'::jsonb,0,'Shutdown order matters.','original'),
('127.819.d.5.M',4,'Cleaning chips off a mill''s table and ways at shutdown helps to:','["hide mistakes", "protect the machine and prepare it for the next shift", "slow production", "add noise"]'::jsonb,1,'Clean machines stay accurate.','original'),
('127.819.d.6.A',3,'A programmer reads a print of a tapered pin, finds the taper angle and uses the tangent function to calculate the change in diameter over a given length so she can enter the end points. She is using:','["a map", "a hunch", "trigonometry to determine coordinates from technical drawings to create a lathe program", "a coin flip"]'::jsonb,2,'Trig finds missing end points.','original'),
('127.819.d.6.A',4,'A right triangle has a 30-degree angle and a hypotenuse of 2 inches. The side opposite the 30-degree angle measures:','["0.5 inch", "2 inches", "1.5 inches", "1 inch"]'::jsonb,3,'sin 30° = 0.5; 2 × 0.5 = 1.','original'),
('127.819.d.6.B',3,'A programmer works out how far to shift a finishing path for a round insert so the turned taper lands on the print size. She is using:','["trigonometry for determining cutter offsets", "chance", "art", "a tape measure only"]'::jsonb,0,'Offsets use trig for angled surfaces.','original'),
('127.819.d.6.B',4,'Nose radius compensation on a lathe is needed most when cutting:','["straight faces only", "tapers and arcs", "nothing", "straight diameters only"]'::jsonb,1,'The tip radius affects angled cuts.','original'),
('127.819.d.6.C',3,'A programmer calculates the RPM needed for a 2-inch diameter at 300 surface feet per minute and sets the feed per revolution from the insert''s chip load. She is using:','["only memory", "no math at all", "appropriate mathematical skills to solve problems while programming a turning center", "only a hunch"]'::jsonb,2,'Math supports every programming decision.','original'),
('127.819.d.6.C',4,'On a lathe, surface speed is the speed at which:','["the turret moves", "the chips fall", "the coolant flows", "the material passes the cutting edge"]'::jsonb,3,'Surface speed relates RPM and diameter.','original'),
('127.819.d.6.D',3,'A student writes a short program that turns the end of a bar flat and then cuts the outside to a 1.25-inch diameter for 3 inches. She is writing:','["a simple program to face and turn", "a report", "a story", "a poem"]'::jsonb,0,'Face-and-turn is a basic program.','original'),
('127.819.d.6.D',4,'In a basic turning program, the program usually ends with:','["a comment only", "an M-code that stops the program and returns to the start", "nothing", "a recipe"]'::jsonb,1,'M30 or M02 ends the program.','original'),
('127.819.d.6.E',3,'A student programs a 0.125-inch corner radius, a 15-degree taper, a groove for an O-ring and a 3/8-16 thread on the same shaft. She is writing:','["a song", "a menu", "a simple program to cut radiuses, angles, grooves and threads", "a letter"]'::jsonb,2,'Contours, grooves and threads add complexity.','original'),
('127.819.d.6.E',4,'A groove for an O-ring is cut with:','["a reamer", "a drill", "a tap", "a grooving tool plunged straight into the part"]'::jsonb,3,'Grooving tools cut grooves.','original'),
('127.819.d.6.F',3,'A programmer turns on tool nose compensation with G42 so the control offsets the path to the right of the programmed profile by the tip radius. She is writing:','["a program using cutter radius compensation", "a program without offsets", "a printed report", "a recipe"]'::jsonb,0,'Compensation keeps profiles accurate.','original'),
('127.819.d.6.F',4,'A G40 command in a CNC program:','["starts the spindle", "cancels tool or cutter radius compensation", "changes the tool", "turns on the coolant"]'::jsonb,1,'G40 cancels compensation.','original'),
('127.819.d.6.G',3,'Rather than programming each roughing pass separately, a programmer uses G71 with a start line, an end line and a depth of cut to remove stock from a shaft. She is writing:','["a shopping list", "a list of sizes", "a program using canned cycles such as G71", "a random sequence"]'::jsonb,2,'Canned cycles condense repetitive moves.','original'),
('127.819.d.6.G',4,'A main advantage of a canned cycle like G71 is that it:','["removes the need for a print", "adds more lines", "hides the toolpath", "makes the program shorter and easier to edit"]'::jsonb,3,'Fewer lines, easier edits.','original'),
('127.819.d.6.H',3,'A student writes a complete program for a NIMS Level 1 turned part that has faces, diameters, a radius, a groove and a thread and then cuts it. She is writing:','["a program and producing a complex part such as a NIMS Level 1 CNC turning project", "a sketch", "a drawing", "a note"]'::jsonb,0,'Complete project from print to part.','original'),
('127.819.d.6.H',4,'Before cutting the first complex part, the student should:','["run it at full speed blindly", "simulate the program and check each tool path", "remove the guard", "skip simulation"]'::jsonb,1,'Simulation catches errors.','original'),
('127.819.d.7.A',3,'A programmer applies sine and cosine to find the X and Y positions of six holes on a bolt circle from a print. She is using:','["a game", "a guess", "trigonometry to determine coordinates from technical drawings to create a mill program", "a map"]'::jsonb,2,'Trig finds hole positions.','original'),
('127.819.d.7.A',4,'For four equally spaced holes on a bolt circle, the angle between neighboring holes is:','["60 degrees", "45 degrees", "120 degrees", "90 degrees"]'::jsonb,3,'360 ÷ 4 = 90.','original'),
('127.819.d.7.B',3,'A programmer uses trigonometry to work out how far a 1/2-inch cutter must be offset from a 45-degree wall so the finished surface is on size. She is using:','["trigonometry to determine cutter offsets", "chance", "a tape measure only", "art"]'::jsonb,0,'Offsets for angled walls use trig.','original'),
('127.819.d.7.B',4,'For an end mill cutting a straight wall, the cutter''s center path is offset from the wall by:','["the cutter''s length", "the cutter''s radius", "zero", "the wall''s thickness"]'::jsonb,1,'Center is one radius away.','original'),
('127.819.d.7.C',3,'A programmer works out that a 1/2-inch, 3-flute end mill at 4,000 RPM with a 0.003-inch chip load needs a particular feed rate and enters it in the program. She is using:','["a coin toss", "only memory", "appropriate mathematical skills to solve problems while programming a machining center", "no math"]'::jsonb,2,'Feed rate is calculated.','original'),
('127.819.d.7.C',4,'For a 3-flute end mill at 4,000 RPM and a 0.003-inch chip load, the feed rate in inches per minute is:','["48", "24", "12", "36"]'::jsonb,3,'4000 × 0.003 × 3 = 36.','original'),
('127.819.d.7.D',3,'A student writes a program that center drills, drills and taps six holes using a drilling cycle and a hole pattern. She is writing:','["a simple program to perform hole operations", "a quiz", "a speech", "a story"]'::jsonb,0,'Hole operations use cycles.','original'),
('127.819.d.7.D',4,'A canned drilling cycle such as G83 is used to:','["face the part", "peck drill deep holes to clear chips", "change tools", "tap threads only"]'::jsonb,1,'Peck cycles clear chips.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_116_v1'
from (values
('127.819.d.7.E',3,'A student programs the profile of a plate with a 0.5-inch corner radius and a 20-degree chamfer on one edge. She is writing:','["a poem", "a menu", "a simple program to cut radiuses and angles", "a recipe"]'::jsonb,2,'Contour programs include arcs and angles.','original'),
('127.819.d.7.E',4,'To cut a clockwise arc on a CNC mill, a programmer uses:','["G54", "M03", "G00", "G02"]'::jsonb,3,'G02 is clockwise circular interpolation.','original'),
('127.819.d.7.F',3,'A programmer adds G41 for left compensation and has the cutter lead in along an arc into the profile instead of dropping straight in. She is writing:','["a program using cutter radius compensation and ramping", "a recipe", "a program with no moves", "a report"]'::jsonb,0,'Lead-ins and ramping protect the tool.','original'),
('127.819.d.7.F',4,'A reason to lead into a cut with an arc rather than a straight plunge is to:','["waste material", "avoid a witness mark and shock to the tool", "add noise", "slow the machine"]'::jsonb,1,'Smooth entry protects the finish.','original'),
('127.819.d.7.G',3,'A student writes a program with pockets, bolt-hole patterns and a profile for a NIMS Level 1 milled part, proves it out and machines it. She is writing:','["a sketch only", "a note", "a program and producing a complex part such as a NIMS Level 1 CNC milling project", "a poster"]'::jsonb,2,'Complete mill project.','original'),
('127.819.d.7.G',4,'After machining a complex milled part, the student should:','["skip the print", "ship it unchecked", "paint it", "inspect each critical feature against the print"]'::jsonb,3,'Inspect before declaring complete.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
